export function setupStickyWatcher(header: HTMLElement, sentinel: HTMLElement) {
  const observer = new IntersectionObserver(([entry]) => {
    header.classList.toggle("is-stuck", !entry.isIntersecting);
  });
  observer.observe(sentinel);
}

